(()=>{const en=location.pathname==='/en'||location.pathname.startsWith('/en/');let path=location.pathname.replace(/^\/en(?=\/|$)/,'')||'/';document.querySelectorAll('.portfolio-language').forEach(link=>{const sync=()=>{link.href=(en?path:'/en'+path)+location.hash;};sync();window.addEventListener('hashchange',sync);link.textContent=en?'한국어':'EN';link.setAttribute('hreflang',en?'ko':'en');link.setAttribute('lang',en?'ko':'en');link.setAttribute('aria-label',en?'한국어로 보기':'Switch to English');});})();
